window.CONSTRUCTORES_SIGDE_LEGALTECH = CONSTRUCTORES_SIGDE_LEGALTECH;
window.buscarConstructorSIGDELegalTech = function(id) {
  return CONSTRUCTORES_SIGDE_LEGALTECH.find(item => item.id === id) || null;
};
window.buscarConstructoresSIGDELegalTech = function(texto = "", materia = "") {
  const q = String(texto || "").trim().toLocaleLowerCase("es-MX");
  const m = String(materia || "").trim().toLocaleLowerCase("es-MX");
  return CONSTRUCTORES_SIGDE_LEGALTECH.filter(item => {
    const im = String(item.materia || "").toLocaleLowerCase("es-MX");
    const matchMateria = !m || im === m;
    const text = `${item.id || ""} ${item.constructor || ""} ${item.submateria || ""} ${item.materia || ""}`.toLocaleLowerCase("es-MX");
    return matchMateria && (!q || text.includes(q));
  });
};
